REVIT_PROPERTY_PALLET_TABLE = pd.DataFrame(REVIT_PROPERTY_PALLET_ROWS)

PROPERTY_PALLET_VALID_NAMES = set(REVIT_PROPERTY_PALLET_TABLE["Property Palette Display Name"].tolist())
PROPERTY_PALLET_VALID_API = set(REVIT_PROPERTY_PALLET_TABLE["API"].tolist())
PROPERTY_PALLET_VALID_VALUES = PROPERTY_PALLET_VALID_NAMES | PROPERTY_PALLET_VALID_API


def get_property_palette_row(name):
    row = REVIT_PROPERTY_PALLET_TABLE[
        (REVIT_PROPERTY_PALLET_TABLE["Property Palette Display Name"] == name)
        | (REVIT_PROPERTY_PALLET_TABLE["API"] == name)
    ]
    return row.iloc[0] if not row.empty else None


