def rf_tools_group_under(name):
    """RF Tools' Group Under code for a Properties palette group: the Revit 2025 GroupTypeId name in
    capitals. Blank stays blank; a name Revit doesn't have is passed through unchanged."""
    name = "" if name is None else str(name).strip()
    group_id = REVIT_GROUP_TYPE_IDS.get(name)
    return group_id.upper() if group_id else name
